/*! igtc-language-role-bridge.min.js (cleaned) */
(function(){
  'use strict';
  var LANG_ALIAS={'ko-kr':'ko','en-us':'en','zh-cn':'zh'};
  window.normalizeLang=function(code){
    if(!code) return 'en';
    code=code.toLowerCase();
    if(LANG_ALIAS[code]) return LANG_ALIAS[code];
    if(code.includes('-')) return code.split('-')[0];
    return code;
  };
  window.getUserRole=function(){
    try { return localStorage.getItem('user_role')||'guest'; }
    catch(_){ return 'guest'; }
  };
})();

/* IGDC/MARU passive empty-slot notice (pipeline-preserving). */
(function(global){
  'use strict';
  if (global.__IGDC_PASSIVE_EMPTY_SLOT_NOTICE_V1__) return;
  global.__IGDC_PASSIVE_EMPTY_SLOT_NOTICE_V1__ = true;

  var COPY={
    ar:'يتم إعداد المحتوى.',bn:'কনটেন্ট প্রস্তুত করা হচ্ছে।',de:'Inhalte werden vorbereitet.',en:'Content is being prepared.',
    es:'El contenido está en preparación.',fa:'محتوا در حال آماده‌سازی است.',fr:'Le contenu est en cours de préparation.',hi:'सामग्री तैयार की जा रही है。',
    hu:'A tartalom előkészítés alatt áll.',id:'Konten sedang disiapkan.',it:'Il contenuto è in preparazione.',ja:'コンテンツを準備中です。',
    ko:'콘텐츠를 준비하고 있습니다.',ms:'Kandungan sedang disediakan.',nl:'De inhoud wordt voorbereid.',pl:'Treść jest przygotowywana.',
    pt:'O conteúdo está sendo preparado.',ru:'Контент готовится.',sv:'Innehållet förbereds.',sw:'Maudhui yanaandaliwa.',
    ta:'உள்ளடக்கம் தயாராகிக் கொண்டிருக்கிறது.',th:'กำลังเตรียมเนื้อหาอยู่',tl:'Inihahanda ang nilalaman.',tr:'İçerik hazırlanıyor.',
    uk:'Вміст готується.',ur:'مواد تیار کیے جا رہے ہیں۔',uz:'Kontent tayyorlanmoqda.',vi:'Nội dung đang được chuẩn bị.',
    zh:'内容正在准备中。',zht:'內容正在準備中。'
  };
  function lang(){
    var raw='';
    try { raw=(document.documentElement&&document.documentElement.getAttribute('lang'))||''; } catch(_e) {}
    raw=String(raw||'en').toLowerCase().replace(/_/g,'-');
    if(raw==='zh-tw'||raw==='zh-hk'||raw==='zh-mo'||raw.indexOf('zh-hant')===0||raw==='zht'||raw.indexOf('zht-')===0) return 'zht';
    if(raw==='zh-cn'||raw==='zh-sg'||raw.indexOf('zh-hans')===0) return 'zh';
    raw=raw.split('-')[0];
    return COPY[raw] ? raw : 'en';
  }
  function message(){ return COPY[lang()] || COPY.en; }
  function direction(){ var code=lang(); return (code==='ar'||code==='fa'||code==='ur') ? 'rtl' : 'ltr'; }
  function isSlot(host){
    if(!host || host.nodeType!==1) return false;
    var key=host.getAttribute('data-psom-key')||'';
    return /^(?:home_|distribution-|media-|social-|network-right$|tour$|donation-)/.test(key);
  }
  function hasExistingContent(host){
    if(!host || !host.querySelector) return false;
    /* Any page-owned card/link/placeholder remains authoritative. */
    return !!host.querySelector('a,button,.thumb-card,.card,.product-card,.ad-box,.donation-card,article,img,video,iframe,[data-item-id],[data-product-id],[data-placeholder]');
  }
  function style(){
    if(document.getElementById('igdc-passive-empty-slot-notice-style')) return;
    var tag=document.createElement('style');
    tag.id='igdc-passive-empty-slot-notice-style';
    tag.textContent='[data-igdc-empty-slot-notice]{box-sizing:border-box;display:flex;align-items:center;justify-content:center;min-height:64px;padding:12px;border:1px dashed rgba(110,120,135,.38);border-radius:10px;background:rgba(246,248,251,.92);color:#5f6b7a;text-align:center;line-height:1.45;font-size:.92rem;cursor:default;pointer-events:none}';
    (document.head||document.documentElement).appendChild(tag);
  }
  function notice(host){
    if(!isSlot(host)) return;
    var existing=host.querySelector(':scope > [data-igdc-empty-slot-notice]');
    if(hasExistingContent(host)) { if(existing) existing.remove(); return; }
    if(existing){
      var copy=message();
      if(existing.textContent!==copy) existing.textContent=copy;
      existing.setAttribute('dir',direction());
      existing.setAttribute('aria-label',copy);
      return;
    }
    var node=document.createElement('div');
    node.setAttribute('data-igdc-empty-slot-notice','1');
    node.setAttribute('role','status');
    node.setAttribute('aria-live','polite');
    node.setAttribute('aria-label',message());
    node.setAttribute('dir',direction());
    node.textContent=message();
    host.appendChild(node);
  }
  function sweep(root){
    var scope=root&&root.querySelectorAll ? root : document;
    if(root&&root.nodeType===1&&isSlot(root)) notice(root);
    var hosts=scope.querySelectorAll ? scope.querySelectorAll('[data-psom-key]') : [];
    for(var i=0;i<hosts.length;i++) notice(hosts[i]);
  }
  function boot(){
    style();
    /* Run after the page's existing renderers. Do not intercept or delay them. */
    setTimeout(function(){ sweep(document); }, 1200);
    var observer=new MutationObserver(function(mutations){
      var dirty=false;
      for(var i=0;i<mutations.length;i++){
        var target=mutations[i].target;
        if(target&&target.nodeType===1&&(isSlot(target)||target.closest&&target.closest('[data-psom-key]'))){ dirty=true; break; }
      }
      if(dirty) setTimeout(function(){ sweep(document); }, 0);
    });
    observer.observe(document.documentElement,{childList:true,subtree:true});
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot,{once:true}); else boot();
})(window);
